import os, re, json
from html.parser import HTMLParser

class JSONLDExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_script = False
        self.jsonld_blocks = []
        self.current_data = ''

    def handle_starttag(self, tag, attrs):
        if tag == 'script':
            attrs_dict = dict(attrs)
            if attrs_dict.get('type') == 'application/ld+json':
                self.in_script = True
                self.current_data = ''

    def handle_endtag(self, tag):
        if tag == 'script' and self.in_script:
            self.in_script = False
            try:
                data = json.loads(self.current_data)
                self.jsonld_blocks.append(data)
            except json.JSONDecodeError as e:
                self.jsonld_blocks.append(('ERROR', str(e), self.current_data[:300]))

    def handle_data(self, data):
        if self.in_script:
            self.current_data += data

pages = [f for f in os.listdir('.') if f.endswith('.html')]
for page in sorted(pages):
    with open(page) as f:
        content = f.read()
    parser = JSONLDExtractor()
    try:
        parser.feed(content)
    except Exception as e:
        print(f'{page}: PARSE ERROR: {e}')
        continue

    if not parser.jsonld_blocks:
        print(f'{page}: NO JSON-LD')
        continue

    for block in parser.jsonld_blocks:
        if isinstance(block, tuple):
            print(f'{page}: INVALID JSON-LD - {block[1]}')
        else:
            ctx = block.get('@context', 'MISSING')
            typ = block.get('@type', 'MISSING')
            title = block.get('name', block.get('headline', block.get('title', 'MISSING')))
            print(f'{page}: @context={ctx}, @type={typ}, name={title}')
